export function parse(phrase: string): string {
  if (!phrase) return "";

  // Replace hyphens with spaces to treat them as word separators
  const normalized = phrase.replace(/-/g, " ");

  // Split by whitespace, filter out empty strings, and take the first letter of each word
  const acronym = normalized
    .split(/\s+/)
    .filter((word) => word.length > 0)
    .map((word) => word[0].toUpperCase())
    .join("");

  return acronym;
}

export function makeDiamond(character: string): string {
  const charCode = character.charCodeAt(0);
  const targetCode = character.toUpperCase().charCodeAt(0);

  if (isNaN(charCode) || charCode !== targetCode) {
    throw new Error("Invalid character");
  }

  const startCode = "A".charCodeAt(0);
  const n = targetCode - startCode;

  if (n < 0) {
    throw new Error("Character must be 'A' or greater");
  }

  const lines: string[] = [];

  // Top half including the middle row
  for (let i = 0; i <= n; i++) {
    const currentChar = String.fromCharCode(startCode + i);
    const spaces = " ".repeat(n - i);

    if (i === 0) {
      lines.push(spaces + currentChar + spaces);
    } else {
      const innerSpaces = " ".repeat(2 * i - 1);
      lines.push(spaces + currentChar + innerSpaces + currentChar + spaces);
    }
  }

  // Bottom half (mirror of top half excluding the middle row)
  for (let i = n - 1; i >= 0; i--) {
    lines.push(lines[i]);
  }

  return lines.join("\n") + "\n";
}
```

Add `answer` (exercise "wordy"):

Parse and evaluate simple math word problems returning the answer as an integer.

## Iteration 0 — Numbers

Problems with no operations simply evaluate to the number given.

> What is 5?

Evaluates to 5.

## Iteration 1 — Addition

Add two numbers together.

> What is 5 plus 13?

Evaluates to 18.

Handle large numbers and negative numbers.

## Iteration 2 — Subtraction, Multiplication and Division

Now, perform the other three operations.

> What is 7 minus 5?

2

> What is 6 multiplied by 4?

24

> What is 25 divided by 5?

5

## Iteration 3 — Multiple Operations

Handle a set of operations, in sequence.

Since these are verbal word problems, evaluate the expression from left-to-right, _ignoring the typical order of operations._

> What is 5 plus 13 plus 6?

24

> What is 3 plus 2 multiplied by 3?

15 (i.e. not 9)

## Iteration 4 — Errors

The parser should reject:

- Unsupported operations ("What is 52 cubed?")
- Non-math questions ("Who is the President of the United States")
- Word problems with invalid syntax ("What is 1 plus plus 2?")

Signature:

```ts
export function answer(question: string): number
```

Examples that must hold:
- answer("What is 5?") returns 5
- answer("What is 1 plus 1?") returns 2
- answer("What is 53 plus 2?") returns 55
- answer("What is 52 cubed?") throws an error whose message contains "Unknown operation"
- answer("Who is the President of the United States?") throws an error whose message contains "Unknown operation"
- answer("What is 1 plus?") throws an error whose message contains "Syntax error"

